Object.assign(window.LLAMANEST_LAB_I18N.en, {
  resetTraining:'Clear saved examples', resetPrompts:'Clear questions and answers', resetTrainingConfirm:'Delete all saved fine tuning examples? Export a copy first if you want to keep them. Trained models are kept.', resetPromptsConfirm:'Delete all saved distillation questions and generated answers? Export your questions first if you want to keep them. Fine tuning examples are kept.', resetDone:'Saved items cleared.',
  guideTitle:'How distillation works here', guideIntro:'A larger teacher model writes example answers. You review them, then train the smaller student model on those question and answer pairs.',
  guideOneTitle:'1. Choose the teacher', guideOne:'For a local teacher, install a GGUF in LlamaNest and select it below. For ChatGPT or another online teacher, collect its answers outside LlamaNest and prepare a JSON file.',
  guideTwoTitle:'2. Prepare and review examples', guideTwo:'Use questions people will really ask. Check every answer, remove mistakes, and add different phrasings. Do not send private material to an online teacher.',
  guideThreeTitle:'3. Send examples to the student', guideThree:'For a local teacher, generate answers below, review them, then choose “Use these answers for fine tuning.” For an online teacher, import its JSON using “Fine tuning → Import a copy.”',
  guideFourTitle:'4. Train and test', guideFour:'Fine tune the smaller student (currently Qwen2.5 0.5B), test with questions outside the dataset, correct mistakes and train again. When satisfied, create the GGUF for the local chat.',
  guideJsonTitle:'JSON format for an online teacher', guideJsonHelp:'Save a UTF-8 .json file with at least five question and answer pairs, then import it in Fine tuning. “prompt” is the question; “completion” is the checked answer.', guideSamplePrompt:'What is a backup?', guideSampleAnswer:'A backup is a copy of your files that you can restore if the originals are lost.'
});
Object.assign(window.LLAMANEST_LAB_I18N.it, {
  resetTraining:'Svuota gli esempi salvati', resetPrompts:'Svuota domande e risposte', resetTrainingConfirm:'Eliminare tutti gli esempi salvati per il fine tuning? Se vuoi conservarli, scarica prima una copia. I modelli già creati restano.', resetPromptsConfirm:'Eliminare tutte le domande della distillazione e le risposte generate? Se vuoi conservarle, scarica prima una copia delle domande. Gli esempi del fine tuning restano.', resetDone:'Elementi salvati eliminati.',
  guideTitle:'Come funziona la distillazione', guideIntro:'Un modello insegnante più grande produce risposte di esempio. Tu le controlli e addestri il modello alunno, più piccolo, sulle coppie domanda e risposta.',
  guideOneTitle:'1. Scegli il modello insegnante', guideOne:'Se è locale, installa un GGUF in LlamaNest e selezionalo qui sotto. Se usi ChatGPT o un altro modello online, raccogli le sue risposte fuori da LlamaNest e prepara un file JSON.',
  guideTwoTitle:'2. Prepara e controlla gli esempi', guideTwo:'Usa domande che le persone farebbero davvero. Verifica ogni risposta, correggi gli errori e aggiungi formulazioni diverse. Non inviare contenuti privati a un insegnante online.',
  guideThreeTitle:'3. Passa gli esempi all’alunno', guideThree:'Con un insegnante locale, genera e controlla le risposte qui sotto, poi premi “Usa queste risposte per il Fine tuning”. Con un insegnante online, apri “Fine tuning → Importa una copia” e carica il JSON.',
  guideFourTitle:'4. Addestra e verifica', guideFour:'Esegui il fine tuning dell’alunno (ora Qwen2.5 0.5B), provalo con domande non presenti negli esempi, correggi gli errori e addestralo di nuovo. Quando sei soddisfatto, crea il GGUF per la chat locale.',
  guideJsonTitle:'Formato JSON per un insegnante online', guideJsonHelp:'Salva un file .json UTF-8 con almeno cinque coppie domanda e risposta e importalo nel Fine tuning. “prompt” è la domanda; “completion” è la risposta verificata.', guideSamplePrompt:'Che cos’è un backup?', guideSampleAnswer:'Un backup è una copia dei file che puoi recuperare se gli originali vanno persi.'
});
Object.assign(window.LLAMANEST_LAB_I18N.de, {
  resetTraining:'Gespeicherte Beispiele löschen', resetPrompts:'Fragen und Antworten löschen', resetTrainingConfirm:'Alle gespeicherten Fine-Tuning-Beispiele löschen? Lade vorher eine Kopie herunter, wenn du sie behalten möchtest. Bereits erstellte Modelle bleiben erhalten.', resetPromptsConfirm:'Alle Distillationsfragen und erzeugten Antworten löschen? Lade vorher eine Kopie der Fragen herunter, wenn du sie behalten möchtest. Fine-Tuning-Beispiele bleiben erhalten.', resetDone:'Gespeicherte Einträge gelöscht.',
  guideTitle:'So funktioniert die Destillation', guideIntro:'Ein größeres Lehrermodell erstellt Beispielantworten. Du prüfst sie und trainierst das kleinere Schülermodell mit diesen Frage-Antwort-Paaren.',
  guideOneTitle:'1. Lehrermodell wählen', guideOne:'Für einen lokalen Lehrer installiere ein GGUF in LlamaNest und wähle es unten aus. Bei ChatGPT oder einem anderen Onlinemodell sammle die Antworten außerhalb von LlamaNest und erstelle eine JSON-Datei.',
  guideTwoTitle:'2. Beispiele vorbereiten und prüfen', guideTwo:'Nutze Fragen, die Menschen wirklich stellen. Prüfe jede Antwort, korrigiere Fehler und ergänze andere Formulierungen. Sende keine privaten Inhalte an ein Onlinemodell.',
  guideThreeTitle:'3. Beispiele an den Schüler geben', guideThree:'Bei einem lokalen Lehrer erzeuge und prüfe die Antworten unten. Wähle dann „Antworten für Fine Tuning verwenden“. Bei einem Onlinemodell importiere die JSON-Datei über „Fine Tuning → Kopie importieren“.',
  guideFourTitle:'4. Trainieren und testen', guideFour:'Trainiere den kleineren Schüler (derzeit Qwen2.5 0.5B), teste ihn mit neuen Fragen, korrigiere Fehler und trainiere erneut. Erstelle danach das GGUF für den lokalen Chat.',
  guideJsonTitle:'JSON-Format für ein Onlinemodell', guideJsonHelp:'Speichere eine UTF-8-.json-Datei mit mindestens fünf Frage-Antwort-Paaren und importiere sie im Fine Tuning. „prompt“ ist die Frage, „completion“ die geprüfte Antwort.', guideSamplePrompt:'Was ist ein Backup?', guideSampleAnswer:'Ein Backup ist eine Kopie deiner Dateien, die du bei Verlust der Originale wiederherstellen kannst.'
});
Object.assign(window.LLAMANEST_LAB_I18N.fr, {
  resetTraining:'Effacer les exemples enregistrés', resetPrompts:'Effacer questions et réponses', resetTrainingConfirm:'Supprimer tous les exemples enregistrés pour l’ajustement fin ? Téléchargez d’abord une copie si vous souhaitez les conserver. Les modèles déjà créés sont conservés.', resetPromptsConfirm:'Supprimer toutes les questions de distillation et les réponses générées ? Téléchargez d’abord une copie des questions si vous souhaitez les conserver. Les exemples d’ajustement fin sont conservés.', resetDone:'Éléments enregistrés effacés.',
  guideTitle:'Comment fonctionne la distillation', guideIntro:'Un modèle enseignant plus grand produit des réponses d’exemple. Vous les vérifiez, puis entraînez le modèle élève, plus petit, avec ces paires question-réponse.',
  guideOneTitle:'1. Choisir le modèle enseignant', guideOne:'Pour un enseignant local, installez un GGUF dans LlamaNest et sélectionnez-le ci-dessous. Avec ChatGPT ou un autre modèle en ligne, recueillez ses réponses hors de LlamaNest et préparez un fichier JSON.',
  guideTwoTitle:'2. Préparer et vérifier les exemples', guideTwo:'Utilisez des questions que les gens poseraient réellement. Vérifiez chaque réponse, corrigez les erreurs et variez les formulations. N’envoyez pas de contenu privé à un modèle en ligne.',
  guideThreeTitle:'3. Transmettre les exemples à l’élève', guideThree:'Avec un enseignant local, générez et vérifiez les réponses ci-dessous, puis choisissez « Utiliser ces réponses pour l’ajustement fin ». Avec un modèle en ligne, importez le JSON via « Ajustement fin → Importer une copie ».',
  guideFourTitle:'4. Entraîner et tester', guideFour:'Entraînez l’élève plus petit (actuellement Qwen2.5 0.5B), testez-le avec de nouvelles questions, corrigez les erreurs et relancez l’entraînement. Créez ensuite le GGUF pour le chat local.',
  guideJsonTitle:'Format JSON pour un modèle en ligne', guideJsonHelp:'Enregistrez un fichier .json UTF-8 avec au moins cinq paires question-réponse, puis importez-le dans l’ajustement fin. « prompt » est la question ; « completion » est la réponse vérifiée.', guideSamplePrompt:'Qu’est-ce qu’une sauvegarde ?', guideSampleAnswer:'Une sauvegarde est une copie de vos fichiers que vous pouvez récupérer si les originaux sont perdus.'
});
Object.assign(window.LLAMANEST_LAB_I18N.es, {
  resetTraining:'Borrar ejemplos guardados', resetPrompts:'Borrar preguntas y respuestas', resetTrainingConfirm:'¿Eliminar todos los ejemplos guardados para el ajuste fino? Descarga antes una copia si quieres conservarlos. Los modelos ya creados se conservan.', resetPromptsConfirm:'¿Eliminar todas las preguntas de destilación y las respuestas generadas? Descarga antes una copia de las preguntas si quieres conservarlas. Los ejemplos de ajuste fino se conservan.', resetDone:'Elementos guardados eliminados.',
  guideTitle:'Cómo funciona la destilación', guideIntro:'Un modelo maestro más grande produce respuestas de ejemplo. Las revisas y entrenas al modelo alumno, más pequeño, con esos pares de pregunta y respuesta.',
  guideOneTitle:'1. Elegir el modelo maestro', guideOne:'Para un maestro local, instala un GGUF en LlamaNest y selecciónalo abajo. Con ChatGPT u otro modelo en línea, recoge sus respuestas fuera de LlamaNest y prepara un archivo JSON.',
  guideTwoTitle:'2. Preparar y revisar los ejemplos', guideTwo:'Usa preguntas que la gente haría de verdad. Comprueba cada respuesta, corrige errores y añade distintas formulaciones. No envíes contenido privado a un modelo en línea.',
  guideThreeTitle:'3. Pasar los ejemplos al alumno', guideThree:'Con un maestro local, genera y revisa las respuestas abajo y elige « Usar estas respuestas para ajuste fino ». Con un modelo en línea, importa el JSON desde « Ajuste fino → Importar una copia ».',
  guideFourTitle:'4. Entrenar y probar', guideFour:'Entrena al alumno más pequeño (ahora Qwen2.5 0.5B), pruébalo con preguntas nuevas, corrige errores y vuelve a entrenar. Después crea el GGUF para el chat local.',
  guideJsonTitle:'Formato JSON para un modelo en línea', guideJsonHelp:'Guarda un archivo .json UTF-8 con al menos cinco pares de pregunta y respuesta e impórtalo en Ajuste fino. « prompt » es la pregunta y « completion » la respuesta verificada.', guideSamplePrompt:'¿Qué es una copia de seguridad?', guideSampleAnswer:'Es una copia de tus archivos que puedes recuperar si pierdes los originales.'
});
Object.assign(window.LLAMANEST_LAB_I18N.en, {guidePromptTitle:'Instructions to give ChatGPT',guidePromptHelp:'Replace the placeholder with your questions, then copy this request into the teacher model.',guideTeacherPrompt:'Answer the questions below accurately. Return only valid JSON, without Markdown, in this shape: {"format":"llamanest-lab-v1","kind":"training","examples":[{"prompt":"question","completion":"checked answer"}]}. Include one pair for each question; keep the original question text. If you cannot answer a question reliably, omit it. Keep each answer under 4,000 characters. Questions: [PASTE YOUR QUESTIONS HERE]'});
Object.assign(window.LLAMANEST_LAB_I18N.it, {guidePromptTitle:'Istruzioni da dare a ChatGPT',guidePromptHelp:'Sostituisci il segnaposto con le tue domande, poi copia questa richiesta nel modello insegnante.',guideTeacherPrompt:'Rispondi con precisione alle domande qui sotto. Restituisci solo JSON valido, senza Markdown, in questa forma: {"format":"llamanest-lab-v1","kind":"training","examples":[{"prompt":"domanda","completion":"risposta verificata"}]}. Crea una coppia per ogni domanda e conserva il testo originale della domanda. Se non puoi rispondere con affidabilità, ometti quella domanda. Mantieni ogni risposta sotto i 4.000 caratteri. Domande: [INCOLLA QUI LE TUE DOMANDE]'});
Object.assign(window.LLAMANEST_LAB_I18N.de, {guidePromptTitle:'Anweisung für ChatGPT',guidePromptHelp:'Ersetze den Platzhalter durch deine Fragen und kopiere diese Anfrage in das Lehrermodell.',guideTeacherPrompt:'Beantworte die folgenden Fragen genau. Gib nur gültiges JSON ohne Markdown in dieser Form zurück: {"format":"llamanest-lab-v1","kind":"training","examples":[{"prompt":"Frage","completion":"geprüfte Antwort"}]}. Erstelle ein Paar pro Frage und behalte den ursprünglichen Fragetext bei. Wenn du eine Frage nicht zuverlässig beantworten kannst, lasse sie weg. Jede Antwort muss unter 4.000 Zeichen bleiben. Fragen: [FRAGEN HIER EINFÜGEN]'});
Object.assign(window.LLAMANEST_LAB_I18N.fr, {guidePromptTitle:'Consigne à donner à ChatGPT',guidePromptHelp:'Remplacez le texte entre crochets par vos questions, puis copiez cette demande dans le modèle enseignant.',guideTeacherPrompt:'Réponds précisément aux questions suivantes. Renvoie uniquement un JSON valide, sans Markdown, sous cette forme : {"format":"llamanest-lab-v1","kind":"training","examples":[{"prompt":"question","completion":"réponse vérifiée"}]}. Crée une paire par question et conserve le texte original de la question. Si tu ne peux pas répondre avec fiabilité, omets cette question. Chaque réponse doit faire moins de 4 000 caractères. Questions : [COLLEZ VOS QUESTIONS ICI]'});
Object.assign(window.LLAMANEST_LAB_I18N.es, {guidePromptTitle:'Instrucciones para ChatGPT',guidePromptHelp:'Sustituye el marcador por tus preguntas y copia esta petición en el modelo maestro.',guideTeacherPrompt:'Responde con precisión a las siguientes preguntas. Devuelve solo JSON válido, sin Markdown, con esta forma: {"format":"llamanest-lab-v1","kind":"training","examples":[{"prompt":"pregunta","completion":"respuesta verificada"}]}. Crea un par por pregunta y conserva el texto original. Si no puedes responder con fiabilidad, omite esa pregunta. Mantén cada respuesta por debajo de 4.000 caracteres. Preguntas: [PEGA AQUÍ TUS PREGUNTAS]'});
